/**
 * Build an app's catalog by scanning its **authoring files** rather than
 * round-tripping the server. Stream-root builders (`app`, …) and
 * own-file children default-export either a `{ ref(refName), def(refName) }`
 * configured entity or a plain `DeployableEntity`. Per-kind catalog shape
 * (stub refs, trigger/outputs bags, `searchTable` vs bag dir) lives on each
 * module's `catalog` facet — this file only walks
 * `ownFileCatalogChildrenOf(parent)`.
 *
 * Assembles two parallel objects:
 *
 *   - `refs` — identity + the app's `fields` bag + one bag per catalog child
 *     (`catalog.catalogBag`), each entry from `catalog.refFromAuthoring`.
 *   - `defs` — configured children's `.def(refName)` plus the app's own
 *     `def()` under `app`.
 *
 * `refName` is always the file's own name (`refNameOf`).
 *
 * `writeAppCatalogFromAuthoring` persists `refs` as a static catalog file
 * at `<appDir>/generated/catalog.ts`.
 */
import { mkdir, readdir, stat, writeFile } from "node:fs/promises";
import { basename, dirname, join, resolve } from "node:path";
import { createWorkspaceLoader } from "../engine/workspace/loader.js";
import { KIND_BY_ID, ownFileCatalogChildrenOf, } from "../graph/index.js";
import { writeCatalogBarrel } from "./org.js";
import { renderCatalog } from "./render.js";
import { assertAuthoringPathForTenant, assertValidAuthoringLayout, isAuthoringHelperFile, isStreamRootAuthoringFile, } from "../engine/workspace/authoring-layout.js";
function isConfiguredEntity(value) {
    return (typeof value === "object" &&
        value !== null &&
        typeof value.ref === "function" &&
        typeof value.def === "function");
}
// Every function in this module exists to reflect whatever's *currently* on
// disk. Within a single `edk pull` an app's own file gets imported here once
// while it's still the import-time reference-only stub (no default export),
// then overwritten with the real `app(...)` call via plain `writeFile`, then
// imported here again. A cached module would return the stale pre-overwrite
// result for that second import — exactly the "does not default-export a
// configured app" failure this avoids.
//
// A FRESH loader per call, which is what buys the freshness described above:
// each one re-reads every workspace file, while the SDK modules behind them
// stay evaluated once for the life of the process.
function authoringLoader(catalogPath) {
    // `catalogPath` is `<wsRoot>/generated/catalog.ts`.
    const root = catalogPath !== undefined ? dirname(dirname(catalogPath)) : process.cwd();
    return createWorkspaceLoader(root);
}
/** The generated catalog's own filename — never treated as an authoring file. */
const CATALOG_FILENAME = "catalog.ts";
function isEntityFile(name) {
    if (name === CATALOG_FILENAME)
        return false;
    if (name === "org.ts" || name === "org.js" || name === "org.mjs")
        return false;
    if (name.endsWith(".d.ts") || name.endsWith(".test.ts"))
        return false;
    if (isAuthoringHelperFile(name))
        return false;
    return name.endsWith(".ts") || name.endsWith(".js") || name.endsWith(".mjs");
}
async function listEntityFiles(dir) {
    let entries;
    try {
        entries = await readdir(dir, { withFileTypes: true });
    }
    catch (err) {
        if (err.code === "ENOENT")
            return [];
        throw err;
    }
    return entries.filter((e) => e.isFile() && isEntityFile(e.name)).map((e) => join(dir, e.name));
}
// Mirrors `src/deploy/directory.ts`'s `SKIP_DIR_NAMES` — `regenerateAppCatalogsUnder`
// runs over the same caller-supplied directory just before discovery, so it
// needs the identical guard against walking into `node_modules`/`.git`/`dist`
// when that directory turns out to be the repo root (e.g. a caller that
// defaulted to `cwd`).
const SKIP_DIR_NAMES = new Set(["node_modules", ".git", "dist", ".edk-state", "generated"]);
/** Same as {@link listEntityFiles}, but walks every subdirectory too. */
async function listEntityFilesRecursive(dir) {
    let entries;
    try {
        entries = await readdir(dir, { withFileTypes: true });
    }
    catch (err) {
        if (err.code === "ENOENT")
            return [];
        throw err;
    }
    const out = [];
    for (const entry of entries) {
        if (entry.isDirectory() && SKIP_DIR_NAMES.has(entry.name))
            continue;
        const full = join(dir, entry.name);
        if (entry.isDirectory())
            out.push(...(await listEntityFilesRecursive(full)));
        else if (entry.isFile() && isEntityFile(entry.name))
            out.push(full);
    }
    return out;
}
/**
 * Expand caller paths into concrete entity source files.
 *
 * Each path may be a single `.ts`/`.js`/`.mjs` authoring file or a directory
 * to walk (same skip rules as {@link listEntityFilesRecursive}). Used by
 * plan/apply so `edk plan path/to/foo.ts bar.ts some/dir` works without
 * moving files into a staging folder.
 *
 * When `tenant` is set (plan/apply), every file must also sit under the
 * authenticated org/instance workspace — see {@link assertAuthoringPathForTenant}.
 */
export async function listEntityFilesFromPaths(paths, tenant) {
    if (paths.length === 0) {
        return listEntityFilesRecursive(process.cwd());
    }
    const out = [];
    for (const raw of paths) {
        const abs = resolve(raw);
        let st;
        try {
            st = await stat(abs);
        }
        catch (err) {
            if (err.code === "ENOENT") {
                throw new Error(`Path does not exist: ${abs}`);
            }
            throw err;
        }
        if (st.isFile()) {
            if (!isEntityFile(basename(abs))) {
                throw new Error(`Not an entity source file: ${abs}`);
            }
            if (tenant)
                assertAuthoringPathForTenant(abs, tenant);
            else
                assertValidAuthoringLayout(abs);
            out.push(abs);
            continue;
        }
        if (st.isDirectory()) {
            for (const file of await listEntityFilesRecursive(abs)) {
                if (tenant)
                    assertAuthoringPathForTenant(file, tenant);
                else
                    assertValidAuthoringLayout(file);
                out.push(file);
            }
            continue;
        }
        throw new Error(`Not a file or directory: ${abs}`);
    }
    return [...new Set(out)].sort();
}
/**
 * The ref name a file's authoring convention implies — its name minus
 * extension. Exported so other discovery code (`src/deploy/directory.ts`)
 * derives the same value from the same rule, rather than each maintaining its
 * own copy of "strip the extension."
 */
export function refNameOf(file) {
    return basename(file).replace(/\.(ts|js|mjs)$/, "");
}
/** Own-file bag directory for a catalog child under `appDir`. */
function catalogChildDir(appDir, child) {
    if (child.authoring.unit !== "ownFile") {
        throw new Error(`entity kind "${child.kind}" has no ownFile authoring bag`);
    }
    return join(appDir, child.authoring.bag);
}
/** Catalog-facet children of a stream-root kind (app / element). */
function catalogChildrenOf(parentKind) {
    return ownFileCatalogChildrenOf(parentKind);
}
/** Stub refs for every file in a child's bag — no import, just a directory listing. */
async function stubRefsForChild(appDir, child, parent) {
    const facet = child.catalog;
    if (!facet.participates)
        return {};
    const out = {};
    for (const file of await listEntityFiles(catalogChildDir(appDir, child))) {
        const refName = refNameOf(file);
        out[refName] = facet.stubRef(refName, parent);
    }
    return out;
}
/**
 * Import every authoring file in a catalog child's bag; build refs via the
 * module's `catalog.refFromAuthoring`. Configured entities also contribute
 * `.def(refName)` into `defsOut[catalogBag]`.
 */
async function loadCatalogChildBag(appDir, child, parent, catalogPath, defsOut) {
    const facet = child.catalog;
    if (!facet.participates)
        return {};
    const loader = authoringLoader(catalogPath);
    const refs = {};
    const defs = {};
    for (const file of await listEntityFiles(catalogChildDir(appDir, child))) {
        const refName = refNameOf(file);
        let mod;
        try {
            mod = (await loader.import(file));
        }
        catch (err) {
            const message = err instanceof Error ? err.message : String(err);
            console.error(`[edk] warning: could not load catalog child ${file}; ` +
                `using typed stub ${parent}.${refName}: ${message}`);
            if (process.env.EDK_DEBUG) {
                console.error(`[EDK_DEBUG] Failed to import ${file}:`, err);
            }
            // Keep the on-disk child visible to sibling authoring even when its full
            // module cannot load yet (for example, a skill that references an
            // element whose catalog is generated later in the same fresh bootstrap).
            // The normal entity-discovery pass still imports the file and reports
            // the real authoring error; this fallback only prevents one unresolved
            // child from erasing its typed catalog ref and cascading into siblings.
            refs[refName] = facet.stubRef(refName, parent);
            continue;
        }
        const defaultExport = mod.default;
        const namedExports = { ...mod };
        delete namedExports.default;
        const catalogRef = facet.refFromAuthoring({
            refName,
            parent,
            defaultExport,
            namedExports,
        });
        if (catalogRef === undefined)
            continue;
        refs[refName] = catalogRef;
        if (isConfiguredEntity(defaultExport)) {
            defs[refName] = defaultExport.def(refName);
        }
    }
    if (Object.keys(defs).length > 0) {
        defsOut[facet.catalogBag] = defs;
    }
    return refs;
}
/**
 * Dedupe by `(kind, handle)`, keeping the *last* occurrence. Matches the
 * pre-dedup behavior of rendering duplicates as duplicate object-literal
 * keys, where normal JS semantics make the last-listed entry win — callers
 * rely on this ordering (e.g. `writeAppCatalogFromAuthoring` lists authored
 * `extraRefs` last so they win; `writeAppCatalog`'s fallback lists `importRefs`
 * first so a freshly authored/pulled file wins over a stale import stub).
 */
function dedupeCatalogRefs(refs) {
    const out = new Map();
    for (const ref of refs) {
        out.set(`${ref.__kind}::${ref.refName}`, ref);
    }
    return [...out.values()];
}
/**
 * Write a throwaway version of `<appDir>/generated/catalog.ts` containing
 * only stub refs — a named export matching the app's own barrel shape, so
 * the org catalog's `import { <appRefName> } from "../../apps/<appRefName>/
 * generated/catalog.js"` picks it up. Immediately overwritten by
 * `writeAppCatalogFromAuthoring`'s real write once child bags resolve.
 */
async function writeStubCatalog(appDir, appRefName, appName, kind, fields, childBags) {
    const generatedDir = join(appDir, "generated");
    await mkdir(generatedDir, { recursive: true });
    const body = { __kind: kind, refName: appRefName, name: appName, fields, ...childBags };
    await writeFile(join(generatedDir, CATALOG_FILENAME), `export const ${appRefName} = ${JSON.stringify(body)};\n`, "utf8");
}
/**
 * Assemble an app's catalog from authoring files on disk — no server
 * round-trip. `appFile` is the app's own authoring file (a `app(...)`
 * result); `appDir` is its containing folder.
 *
 * Writes a throwaway stub version of `<appDir>/generated/catalog.ts` before
 * importing any child authoring file (see `writeStubCatalog`) — a sibling
 * may reference another sibling's catalog entry that doesn't exist on disk
 * yet. The stub is overwritten with the real catalog by this function's
 * caller.
 */
export async function buildAppCatalogFromAuthoring(appDir, appFile, orgCatalogPath) {
    // `appDir` is `<wsRoot>/apps/<handle>` or `<wsRoot>/elements/<handle>`.
    const resolvedOrgCatalogPath = orgCatalogPath ?? join(dirname(dirname(appDir)), "generated", "catalog.ts");
    const loader = authoringLoader(resolvedOrgCatalogPath);
    const appMod = (await loader.import(appFile));
    if (!isConfiguredEntity(appMod.default)) {
        throw new Error(`${appFile} does not default-export a configured app (a app(...) result)`);
    }
    const app = appMod.default;
    const appRefName = refNameOf(appFile);
    const appRef = app.ref(appRefName);
    const fields = appRef.fields ?? {};
    const parentKind = (appRef.__kind === "element" ? "element" : "app");
    const children = catalogChildrenOf(parentKind);
    const stubBags = {};
    for (const child of children) {
        if (!child.catalog.participates)
            continue;
        stubBags[child.catalog.catalogBag] = await stubRefsForChild(appDir, child, appRefName);
    }
    await writeStubCatalog(appDir, appRefName, appRef.name, appRef.__kind, fields, stubBags);
    // The stub above makes THIS app's own generated/catalog.ts self-consistent
    // for intra-app sibling references (e.g. one agent referencing another's
    // catalog entry) — but a sibling file resolves `@catalog` through the ORG
    // ROOT's barrel, which re-exports this app from that same file. On a
    // brand-new app's very first regen, the org barrel doesn't reference this
    // app yet, so `catalog.<thisApp>...` inside a sibling agent/skill file
    // (e.g. an agent's own `skillAccess` pointing at a sibling skill) resolves
    // to `undefined` and throws — silently dropping that file from its bag
    // (loadBag/loadV2Bag treat a load failure as "skip", by design, for other
    // legitimate not-yet-resolvable cases). Refresh the org barrel now so the
    // stub is at least visible before loading any sibling file below.
    await writeCatalogBarrel(dirname(dirname(appDir)));
    const childRefBags = {};
    const childDefBags = {};
    for (const child of children) {
        if (!child.catalog.participates)
            continue;
        childRefBags[child.catalog.catalogBag] = await loadCatalogChildBag(appDir, child, appRefName, resolvedOrgCatalogPath, childDefBags);
    }
    const refs = {
        __kind: appRef.__kind,
        refName: appRefName,
        name: appRef.name,
        fields,
        ...childRefBags,
    };
    const defs = {
        refName: appRefName,
        name: appRef.name,
        app: app.def(appRefName),
        ...childDefBags,
    };
    return { refs, defs };
}
/**
 * Build the app's catalog from authoring files and persist `refs` as a static
 * catalog file at `<appDir>/generated/catalog.ts` — distinct from the app's own
 * authoring files, so this never clobbers hand-authored source. Returns `defs`
 * too (not yet written to disk) for callers that need the whole app's deployable
 * entities in one pass.
 *
 * `extraRefs` merges in refs that don't (yet) have authoring files of their
 * own — e.g. search tables, sourced from state by the app-pull orchestrator —
 * so they keep showing up in the catalog instead of being dropped now that the
 * old embedded-in-the-app-file catalog section is gone.
 */
export async function writeAppCatalogFromAuthoring(appDir, appRefName, appName, appFile, extraRefs = []) {
    // Derive org catalog path once — passed to buildAppCatalogFromAuthoring and reused
    // for the trigger-kind scan so both use the identical `@catalog` alias.
    const orgCatalogPath = join(dirname(dirname(appDir)), "generated", "catalog.ts");
    const { refs, defs } = await buildAppCatalogFromAuthoring(appDir, appFile, orgCatalogPath);
    const fields = refs.fields ?? {};
    const parentKind = (refs.__kind === "element" ? "element" : "app");
    const fromBags = [];
    for (const child of catalogChildrenOf(parentKind)) {
        if (!child.catalog.participates)
            continue;
        const bag = refs[child.catalog.catalogBag];
        if (bag === undefined)
            continue;
        fromBags.push(...Object.values(bag));
    }
    const flatRefs = dedupeCatalogRefs([...Object.values(fields), ...fromBags, ...extraRefs]);
    // Fields resolve live off the app's own file (see `renderCatalog`'s `ownFile`
    // param) — never baked, so adding/editing/removing a field never requires
    // re-running this writer. `flatRefs`' field entries still flow through
    // (extraRefs/dedupe), but rendering ignores them when `ownFile` is set.
    const ownFile = { importPath: `../${basename(appFile).replace(/\.ts$/, ".js")}`, identifier: `${appRefName}Own` };
    const source = renderCatalog({ kind: refs.__kind, refName: appRefName, name: appName }, flatRefs, undefined, ownFile);
    const generatedDir = join(appDir, "generated");
    const catalogPath = join(generatedDir, CATALOG_FILENAME);
    await mkdir(generatedDir, { recursive: true });
    await writeFile(catalogPath, source, "utf8");
    return { catalogPath, defs };
}
/**
 * Write/refresh `<appDir>/generated/catalog.ts` regardless of whether the app has been
 * fully pulled yet. If `appFile` already default-exports a configured app (a
 * `app(...)` pull), this is exactly {@link writeAppCatalogFromAuthoring}.
 * Otherwise — `edk import app` ran but `edk pull app` hasn't, so `appFile` is
 * just the old reference-only stub with no default export — falls back to
 * `importRefs` (the import-time fields/searchTables) merged with whatever
 * own-file children already have authoring files in this folder.
 */
export async function writeAppCatalog(appDir, appRefName, appName, appFile, importRefs = [], kind = "app", namespace) {
    // Derive the workspace catalog path for the `@catalog` alias so entity files
    // that `import catalog from "@catalog"` can be loaded. `appDir` is
    // `<wsRoot>/apps/<handle>`; the org catalog lives at `<wsRoot>/generated/catalog.ts`.
    const wsRoot = dirname(dirname(appDir));
    const orgCatalogPath = join(wsRoot, "generated", "catalog.ts");
    const loader = authoringLoader(orgCatalogPath);
    let appMod;
    try {
        appMod = (await loader.import(appFile));
    }
    catch {
        appMod = undefined;
    }
    if (appMod !== undefined && isConfiguredEntity(appMod.default)) {
        const { catalogPath } = await writeAppCatalogFromAuthoring(appDir, appRefName, appName, appFile, importRefs);
        return { catalogPath };
    }
    const parentKind = kind;
    // Ensure parent kind is registered (loud if graph drifts).
    if (KIND_BY_ID.get(parentKind) === undefined) {
        throw new Error(`unknown catalog parent kind "${kind}"`);
    }
    const fromBags = [];
    const unusedDefs = {};
    for (const child of catalogChildrenOf(parentKind)) {
        const bag = await loadCatalogChildBag(appDir, child, appRefName, orgCatalogPath, unusedDefs);
        fromBags.push(...Object.values(bag));
    }
    const flatRefs = dedupeCatalogRefs([...importRefs, ...fromBags]);
    const source = renderCatalog({ kind, refName: appRefName, name: appName, ...(namespace !== undefined ? { namespace } : {}) }, flatRefs);
    const generatedDir = join(appDir, "generated");
    const catalogPath = join(generatedDir, CATALOG_FILENAME);
    await mkdir(generatedDir, { recursive: true });
    await writeFile(catalogPath, source, "utf8");
    return { catalogPath };
}
/**
 * Regenerate the per-entity catalog for every app/element authoring file
 * found anywhere under `dir` — the same kind of file `edk plan`/`edk apply`
 * discover as deployable entities. Run this **before** plan/apply discovery:
 * an automation file that imports its owning app's/element's `catalog.ts`
 * needs that file to reflect whatever own-file children exist on disk right
 * now, not a stale snapshot from the last time the catalog was written.
 *
 * A file that fails to load is silently skipped here — `discoverV2Entities`
 * (run right after this, by the caller) is what surfaces load errors to the
 * user; duplicating that reporting here would just be noise.
 *
 * `pathOrPaths` may be one directory (historical), one authoring file, or a
 * mix of files and directories — same expansion rules as plan/apply discovery.
 *
 * Pass `tenant` from plan/apply so paths are gated to the authenticated
 * org/instance workspace.
 */
export async function regenerateAppCatalogsUnder(pathOrPaths, tenant) {
    const paths = typeof pathOrPaths === "string" ? [pathOrPaths] : pathOrPaths;
    const out = [];
    for (const file of await listEntityFilesFromPaths(paths, tenant)) {
        if (!isStreamRootAuthoringFile(file))
            continue;
        // A root app/element file may itself `import catalog from "@catalog"`
        // (e.g. a relation field referencing another workspace entity by
        // token) — without this alias that import fails to resolve and the
        // file is silently skipped below, exactly as if it were broken. Root
        // stream-root files are always `<orgRoot>/apps|elements/<ref>/<ref>.ts`
        // (two directories below the org root), so this derivation is only
        // guaranteed correct for THOSE files — but that's exactly the shape
        // this function's own output depends on; a wrong guess for a deeper
        // own-file child (agents/, skills/, …) is harmless, since such a
        // file's `ref.__kind` is never "app"/"element" and its result is
        // discarded below regardless of whether it loaded at all.
        const orgRoot = dirname(dirname(dirname(file)));
        const loader = authoringLoader(join(orgRoot, "generated", CATALOG_FILENAME));
        let mod;
        try {
            mod = (await loader.import(file));
        }
        catch (err) {
            if (process.env.EDK_DEBUG) {
                console.error(`[EDK_DEBUG] Failed to import ${file}:`, err);
            }
            continue;
        }
        if (!isConfiguredEntity(mod.default))
            continue;
        const appRefName = refNameOf(file);
        const ref = mod.default.ref(appRefName);
        if (ref.__kind !== "app" && ref.__kind !== "element")
            continue;
        const { catalogPath } = await writeAppCatalogFromAuthoring(dirname(file), appRefName, ref.name, file, []);
        out.push({ appRefName, appName: ref.name, kind: ref.__kind, catalogPath });
    }
    return out;
}
